/// Nonterminals: the forms a value takes.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Nt {
    /// uniform value in an SGPR
    S = 0,
    /// value in a VGPR
    V = 1,
    /// constant
    K = 2,
    /// SALU source: an SGPR or a constant
    Ssrc = 3,
    /// VALU source: a VGPR, an SGPR or a constant
    Vsrc = 4,
}

/// Terminals: integer operations and tree leaves.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Term {
    Add,
    Sub,
    Mul,
    Mulhu,
    Mulhi,
    And,
    Or,
    Xor,
    Shl,
    Lshr,
    Ashr,
    Smin,
    Smax,
    Konst,
    Sreg,
    Vreg,
}

/// The terminal of an IR operation, if the grammar has one.
pub fn term_of(kind: OpKind) -> Option<Term> {
    match kind {
        OpKind::Add => Some(Term::Add),
        OpKind::Sub => Some(Term::Sub),
        OpKind::Mul => Some(Term::Mul),
        OpKind::UmulHi => Some(Term::Mulhu),
        OpKind::SmulHi => Some(Term::Mulhi),
        OpKind::And => Some(Term::And),
        OpKind::Or => Some(Term::Or),
        OpKind::Xor => Some(Term::Xor),
        OpKind::Shl => Some(Term::Shl),
        OpKind::Lshr => Some(Term::Lshr),
        OpKind::Ashr => Some(Term::Ashr),
        OpKind::Smin => Some(Term::Smin),
        OpKind::Smax => Some(Term::Smax),
        _ => None,
    }
}

/// The leaf terminals: constants, uniform and divergent registers.
pub const KONST: Term = Term::Konst;
pub const SREG: Term = Term::Sreg;
pub const VREG: Term = Term::Vreg;

/// What reducing a rule emits.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Action {
    /// A leaf: the value computed elsewhere.
    Leaf,
    /// A chain rule: the node as another nonterminal.
    Chain(Nt),
    /// One operation, through isel's own selection of it (`int_bin`).
    Hand(OpKind),
    /// A three-source VOP3 of pattern variables `vars`; `commute`: put an
    /// inner commutative operation's VGPR source second, as isel orders it.
    V3 { op: Opc, vars: [u8; 3], commute: bool },
    /// `s_lshl<k>_add_u32 a, b` for variables (a, k, b).
    LshlAdd { vars: [u8; 3] },
}

