                let x1 = t.kid(n, 0);
                if t.term(x1) == Term::Or {
                    let v_a = t.kid(x1, 0);
                    let v_b = t.kid(x1, 1);
                    let v_c = t.kid(n, 1);
                    if t.fits3(v_a, v_b, v_c) {
                        c[1].offer(t.cost(v_a, Nt::Vsrc) + t.cost(v_b, Nt::Vsrc) + t.cost(v_c, Nt::Vsrc) + 2, 47);
                    }
                }
